-- Supabase schema for Mannequin Care admin features
-- Generated by Zencoder on 2025-11-10

-- Extensions
create extension if not exists "pgcrypto";

-- Helper function for updated_at
create or replace function public.set_updated_at()
returns trigger as $$
begin
  new.updated_at = timezone('utc', now());
  return new;
end;
$$ language plpgsql;

-- Enums
create type public.user_role as enum ('customer', 'staff', 'admin');
create type public.product_status as enum ('draft', 'active', 'archived');
create type public.blog_status as enum ('draft', 'scheduled', 'published');
create type public.review_status as enum ('pending', 'approved', 'rejected');
create type public.order_status as enum ('pending', 'processing', 'completed', 'cancelled', 'refunded');
create type public.payment_status as enum ('pending', 'authorized', 'paid', 'failed', 'refunded');
create type public.address_type as enum ('billing', 'shipping');

-- Profiles table (extends auth.users)
create table if not exists public.profiles (
  id uuid primary key references auth.users on delete cascade,
  display_name text,
  role public.user_role not null default 'customer',
  avatar_url text,
  phone text,
  metadata jsonb default '{}'::jsonb,
  created_at timestamptz not null default timezone('utc', now()),
  updated_at timestamptz not null default timezone('utc', now())
);

create trigger update_profiles_updated_at
  before update on public.profiles
  for each row
  execute function public.set_updated_at();

create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  insert into public.profiles (id, display_name, role, metadata)
  values (
    new.id,
    coalesce(new.raw_user_meta_data->>'full_name', new.email),
    coalesce((coalesce(new.raw_user_meta_data, '{}'::jsonb)->>'role')::public.user_role, 'customer'),
    jsonb_build_object('email', new.email)
    || case
         when coalesce(new.raw_user_meta_data, '{}'::jsonb) ? 'role'
         then jsonb_build_object('role', coalesce(new.raw_user_meta_data, '{}'::jsonb)->>'role')
         else '{}'::jsonb
       end
  )
  on conflict (id) do update
    set display_name = excluded.display_name,
        role = excluded.role,
        metadata = public.profiles.metadata || excluded.metadata;
  return new;
end;
$$;

create or replace function public.handle_user_update()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  update public.profiles
    set
      display_name = coalesce(new.raw_user_meta_data->>'full_name', new.email, display_name),
      role = coalesce((coalesce(new.raw_user_meta_data, '{}'::jsonb)->>'role')::public.user_role, role),
      metadata =
        coalesce(metadata, '{}'::jsonb)
        || jsonb_build_object('email', new.email)
        || case
             when coalesce(new.raw_user_meta_data, '{}'::jsonb) ? 'role'
             then jsonb_build_object('role', coalesce(new.raw_user_meta_data, '{}'::jsonb)->>'role')
             else '{}'::jsonb
           end,
      updated_at = timezone('utc', now())
  where id = new.id;
  return new;
end;
$$;

create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();

create trigger on_auth_user_updated
  after update on auth.users
  for each row execute function public.handle_user_update();

-- User addresses
create table if not exists public.user_addresses (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.profiles(id) on delete cascade,
  type public.address_type not null,
  full_name text not null,
  phone text not null,
  street_address text not null,
  city text not null,
  state text not null,
  postal_code text not null,
  country text not null default 'India',
  is_default boolean not null default false,
  created_at timestamptz not null default timezone('utc', now()),
  updated_at timestamptz not null default timezone('utc', now())
);

create trigger update_user_addresses_updated_at
  before update on public.user_addresses
  for each row
  execute function public.set_updated_at();

