-- Profiles policies
create policy "Profiles are viewable by owner or admins" on public.profiles
  for select using (
    auth.uid() = id or
    public.is_admin()
  );

create policy "Users can update own profile" on public.profiles
  for update using (auth.uid() = id);

create policy "Admins manage profiles" on public.profiles
  for all using (public.is_admin());

-- User addresses policies
create policy "Users can manage own addresses" on public.user_addresses
  for all using (auth.uid() = user_id);

create policy "Admins can view all addresses" on public.user_addresses
  for select using (public.is_admin());

-- Admin-only policies (products, categories, etc.)
create policy "Admins manage categories" on public.product_categories
  for all using (public.is_admin());

create policy "Public can view categories" on public.product_categories
  for select using (true);

create policy "Admins manage products" on public.products
  for all using (public.is_admin());

create policy "Public can view active products" on public.products
  for select using (status = 'active');

create policy "Admins manage product media" on public.product_media
  for all using (public.is_admin());

create policy "Public can view product media" on public.product_media
  for select using (true);

create policy "Admins manage orders" on public.orders
  for all using (public.is_admin());

create policy "Admins manage order items" on public.order_items
  for all using (public.is_admin());

create policy "Admins manage blogs" on public.blog_posts
  for all using (public.is_admin());

create policy "Admins manage reviews" on public.product_reviews
  for all using (public.is_admin());

create policy "Public can view approved reviews" on public.product_reviews
  for select using (status = 'approved');

create policy "Customers can view own reviews" on public.product_reviews
  for select using (auth.uid() = user_id);

create policy "Admins manage settings" on public.site_settings
  for all using (public.is_admin());

-- Customer access for orders, reviews, cart, wishlist
create policy "Customers select own orders" on public.orders
  for select using (auth.uid() = user_id);

create policy "Customers select own order items" on public.order_items
  for select using (
    exists (
      select 1 from public.orders o
      where o.id = order_items.order_id and o.user_id = auth.uid()
    )
  );

create policy "Customers manage own reviews" on public.product_reviews
  for all using (auth.uid() = user_id);

create policy "Customers can insert reviews" on public.product_reviews
  for insert with check (auth.uid() = user_id);

create policy "Customers manage cart" on public.cart_items
  for all using (auth.uid() = user_id);

create policy "Customers manage wishlist" on public.wishlist_items
  for all using (auth.uid() = user_id);

-- Useful indexes
create index if not exists idx_user_addresses_user on public.user_addresses(user_id);
create index if not exists idx_user_addresses_type on public.user_addresses(user_id, type);
create unique index if not exists idx_user_addresses_default on public.user_addresses(user_id, type) where is_default = true;
create index if not exists idx_product_categories_parent on public.product_categories(parent_id);
create index if not exists idx_products_main_category on public.products(main_category_id);
create index if not exists idx_products_sub_category on public.products(sub_category_id);
create index if not exists idx_products_status on public.products(status);
create index if not exists idx_orders_user on public.orders(user_id);
create index if not exists idx_blog_posts_status on public.blog_posts(status);
create index if not exists idx_reviews_product on public.product_reviews(product_id);

-- Stock decrement helper (called server-side after order creation)
create or replace function public.decrement_stock(p_product_id uuid, p_quantity integer)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  update public.products
    set stock = greatest(0, stock - p_quantity)
  where id = p_product_id;
end;
$$;

-- RLS: allow authenticated customers to insert their own orders
create policy "Customers can place orders" on public.orders
  for insert with check (auth.uid() = user_id or user_id is null);

-- RLS: allow authenticated customers to insert their own order items
create policy "Customers can insert order items" on public.order_items
  for insert with check (
    exists (
      select 1 from public.orders o
      where o.id = order_items.order_id
        and (o.user_id = auth.uid() or o.user_id is null)
    )
  );
